// Verifica la firma HMAC que pone la app: X-IMMC-Signature = sha256=HMAC(secret, `${timestamp}.${body}`).
// Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto en n8n y la variable IMMC_WEBHOOK_SECRET (= N8N_WEBHOOK_SECRET de la app).
const crypto = require('crypto');
const item = $input.first().json;
const h = item.headers || {};
const secret = $env.IMMC_WEBHOOK_SECRET;
const ts = h['x-immc-timestamp'];
const sig = h['x-immc-signature'] || '';
const raw = JSON.stringify(item.body);
if (secret) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
  const ok = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
  if (!ok) throw new Error('Firma inválida: notificación rechazada');
  if (Math.abs(Date.now() - Date.parse(ts)) > 10 * 60 * 1000) throw new Error('Firma vencida (más de 10 min)');
}
const p = item.body.payload;
if (!p || p.channel !== 'whatsapp') return [];
// Un item por destinatario de WhatsApp.
return (p.recipients || []).map((r) => ({ json: {
  to: String(r.address).replace(/\D/g, ''),
  name: r.name,
  notificationId: p.notificationId,
  incidentId: p.incidentId,
  kind: p.kind,
  severity: p.severity,
  template: p.whatsappTemplate,
  text: p.text
} }));
